class Solution:
    def findLHS(self, nums: list[int]) -> int:
        ordered = sorted(nums)
        left = best = 0
        for right, value in enumerate(ordered):
            while value - ordered[left] > 1:
                left += 1
            if value - ordered[left] == 1:
                best = max(best, right - left + 1)
        return best
